sys_script_include.script:
var SchemaRegistry = Class.create();
SchemaRegistry.prototype = {
    initialize: function() {

        /** NEW schemas MUST include the following properties:
         * @httpMethod type:str this is the name of your HTTP method defined in the REST Message record.
         * @table type:str
         * @requiresDeviceGroup type:boolean
         * @key: type:str; unique identifier
         * @dedupe: type:bool, optional; deduplicate entries - only necessary where multiple entries exist per device group.
         * @map type:obj
         *  */

        this._schemas = {};

        // register Panorama schemas
        this._schemas['application_data'] = {
            httpMethod: "retrievePanoramaApplications",
            table: "x_835786_firewall_panorama_application_profile_staging",
            requiresDeviceGroup: false,
            key: "u_name",
            dedupe: false,
            map: {
                u_name: "@name",
                u_port: "default.port.member",
                u_subcategory: "subcategory",
                category: "category"
            },
        };

        this._schemas['url_categories'] = {
            httpMethod: "retrieveUrlCategories",
            table: "x_kpmg7_panorama_f_url_categories_import",
            requiresDeviceGroup: true,
            key: "u_name",
            dedupe: true,
            map: {
                u_name: "@name",
                u_type: "type",
                u_description: "description",
            },
        };
    },

    getSchema: function(objectType) {
        return this._schemas[objectType];
    },

    listSchemas: function() {
        return Object.keys(this._schemas);
    },

    type: 'SchemaRegistry'
};
